import React from 'react';
import Logo from '../assets/hello.gif';
import styled from 'styled-components';

export default function Welcome({ currentUser }) {
  return (
    <Component>
      <div className="gif">
        <img src={Logo} alt="" />
      </div>
      <div className="text">
        <h1>
          Welcome bacK !! <br />
          <span>{currentUser?.username}</span>
        </h1>
        <h3>Please select a chat to start</h3>
      </div>
    </Component>
  );
}

const Component = styled.div`
  height: 100%;
  flex: 1 1 65%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  row-gap: 15px;
  .gif {
    overflow: hidden;
    width: 50%;
    display: flex;
    justify-content: center;
    align-items: center;
    img {
      height: 90%;
      width: 90%;
      filter: drop-shadow(0px 2px 4px #9669ac);
    }
  }
  .text {
    width: 50%;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
    h1 {
      color: #ffffffd1;
      font: 600 2rem var(--arimaFont);
      text-align: center;
      span {
        color: #a23ed3;
      }
    }
  }
`;
